25	public class FormBodyHandler implements GenericRuntimeConfigurableServerRestHandler<RuntimeConfiguration> {
26	
27	    private final boolean alsoSetInputStream;
28	    private final Supplier<Executor> executorSupplier;
29	    private final Set<String> fileFormNames;
30	    private volatile FormParserFactory formParserFactory;
31	
32	    public FormBodyHandler(boolean alsoSetInputStream, Supplier<Executor> executorSupplier, Set<String> fileFormNames) {
33	        this.alsoSetInputStream = alsoSetInputStream;
34	        this.executorSupplier = executorSupplier;
35	        this.fileFormNames = fileFormNames;
36	    }
37	
38	    @Override
39	    public Class<RuntimeConfiguration> getConfigurationClass() {
40	        return RuntimeConfiguration.class;
41	    }
42	
43	    @Override
44	    public void configure(RuntimeConfiguration configuration) {
45	        formParserFactory = FormParserFactory.builder(false, executorSupplier)
46	                .addParser(new MultiPartParserDefinition(executorSupplier)
47	                        .setFileSizeThreshold(0)
48	                        .setMaxAttributeSize(configuration.limits().maxFormAttributeSize())
49	                        .setMaxEntitySize(configuration.limits().maxBodySize().orElse(-1L))
50	                        .setDeleteUploadsOnEnd(configuration.body().deleteUploadedFilesOnEnd())
51	                        .setFileContentTypes(configuration.body().multiPart().fileContentTypes())
52	                        .setDefaultCharset(configuration.body().defaultCharset().name())
53	                        .setTempFileLocation(Path.of(configuration.body().uploadsDirectory())))
54	
55	                .addParser(new FormEncodedDataDefinition()
56	                        .setMaxAttributeSize(configuration.limits().maxFormAttributeSize())
57	                        .setDefaultCharset(configuration.body().defaultCharset().name()))
58	                .build();
59	
60	        try {
61	            Files.createDirectories(Paths.get(configuration.body().uploadsDirectory()));
62	        } catch (IOException e) {
63	            throw new UncheckedIOException(e);
64	        }
65	    }
66	
67	    @Override
68	    public void handle(ResteasyReactiveRequestContext requestContext) throws Exception {
69	        // in some cases, with sub-resource locators or via request filters,
70	        // it's possible we've already read the entity
71	        if (requestContext.getFormData() != null) {
72	            // let's not set it twice
73	            return;
74	        }
75	        FormData existingParsedForm = requestContext.serverRequest().getExistingParsedForm();
76	        if (existingParsedForm != null) {
77	            requestContext.setFormData(existingParsedForm);
78	            return;
79	        }
80	        FormDataParser factory = formParserFactory.createParser(requestContext, fileFormNames);
81	        if (factory == null) {
82	            return;
83	        }
84	        if (BlockingOperationSupport.isBlockingAllowed()) {
85	            //blocking IO approach
86	            CapturingInputStream cis = null;
87	            if (alsoSetInputStream) {
88	                // the TCK allows the body to be read as a form param and also as a body param
89	                // the spec is silent about this
90	                // TODO: this is really really horrible and hacky and needs to be fixed.
91	                cis = new CapturingInputStream(requestContext.getInputStream());
92	                requestContext.setInputStream(cis);
93	            }
94	            factory.parseBlocking();
95	            if (alsoSetInputStream) {
96	                requestContext.setInputStream(new ByteArrayInputStream(cis.baos.toByteArray()));
97	            }
98	        } else if (alsoSetInputStream) {
99	            requestContext.suspend();
100	            executorSupplier.get().execute(new Runnable() {
101	                @Override
102	                public void run() {
103	                    try {
104	                        CapturingInputStream cis = new CapturingInputStream(requestContext.getInputStream());
105	                        requestContext.setInputStream(cis);
106	                        factory.parseBlocking();
107	                        requestContext.setInputStream(new ByteArrayInputStream(cis.baos.toByteArray()));
108	                        requestContext.resume();
109	                    } catch (Throwable t) {
110	                        requestContext.resume(t);
111	                    }
112	                }
113	            });
114	        } else {
115	            //parse will auto resume
116	            factory.parse();
117	        }
118	    }
119	
120	    static final class CapturingInputStream extends InputStream {
121	
122	        ByteArrayOutputStream baos = new ByteArrayOutputStream();
123	        final InputStream delegate;
124	
125	        CapturingInputStream(InputStream delegate) {
126	            this.delegate = delegate;
127	        }
128	
129	        @Override
130	        public int read() throws IOException {
131	            int res = delegate.read();
132	            if (res != -1) {
133	                baos.write(res);
134	            }
135	            return res;
136	        }
137	    }
138	
139	}
