import org.jboss.shrinkwrap.api.spec.JavaArchive;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.RegisterExtension;

import io.quarkus.qute.Template;
import io.quarkus.qute.TemplateInstance;
import io.quarkus.test.QuarkusUnitTest;
import io.restassured.RestAssured;
import io.restassured.config.EncoderConfig;
import io.restassured.config.RestAssuredConfig;
import io.restassured.http.ContentType;
import io.smallrye.mutiny.Uni;

public class CsrfTest {

    private static final String COOKIE_NAME = "csrf-token";
    private static final String HEADER_NAME = "X-CSRF-TOKEN";

    @RegisterExtension
    static final QuarkusUnitTest config = new QuarkusUnitTest()
            .setArchiveProducer(() -> ShrinkWrapHelper.archive());

    static final class ShrinkWrapHelper {
        static JavaArchive archive() {
            return org.jboss.shrinkwrap.api.ShrinkWrap.create(JavaArchive.class)
                    .addClasses(TestResource.class)
                    .addAsResource("templates/csrfToken.html");
        }
    }

    @Test
    public void testForm() {
        String token = RestAssured.when().get("/csrfTokenForm").then().statusCode(200).cookie(COOKIE_NAME).extract()
                .cookie(COOKIE_NAME);

        RestAssuredConfig restAssuredConfig = RestAssured.config()
                .encoderConfig(EncoderConfig.encoderConfig().encodeContentTypeAs("multipart/form-data", ContentType.TEXT));

        // Missing token form field
        RestAssured.given().cookie(COOKIE_NAME, token).config(restAssuredConfig)
                .formParam("name", "testName")
                .contentType(ContentType.URLENC)
                .when().post("csrfTokenForm").then().statusCode(400);

        // Wrong token form field
        RestAssured.given().cookie(COOKIE_NAME, token).config(restAssuredConfig)
                .formParam("csrf-token", "WRONG")
                .formParam("name", "testName")
                .contentType(ContentType.URLENC)
                .when().post("csrfTokenForm").then().statusCode(400);

        // Correct token form field
        RestAssured.given().cookie(COOKIE_NAME, token).config(restAssuredConfig)
                .formParam("csrf-token", token)
                .formParam("name", "testName")
                .contentType(ContentType.URLENC)
                .when().post("csrfTokenForm").then().statusCode(200).body(equalTo("testName"));
    }

    @Test
    public void testNoBody() {
        String token = RestAssured.when().get("/csrfTokenForm").then().statusCode(200).cookie(COOKIE_NAME).extract()
                .cookie(COOKIE_NAME);

        // No header
        RestAssured.given().cookie(COOKIE_NAME, token)
                .when().post("csrfTokenPost").then().statusCode(400);

        // Wrong header
        RestAssured.given().cookie(COOKIE_NAME, token).header(HEADER_NAME, "WRONG")
                .when().post("csrfTokenPost").then().statusCode(400);

        // Correct header
        RestAssured.given().cookie(COOKIE_NAME, token).header(HEADER_NAME, token)
                .when().post("csrfTokenPost").then().statusCode(200).body(equalTo("no user"));
    }

    @Test
    public void testWithBody() {
        String token = RestAssured.when().get("/csrfTokenForm").then().statusCode(200).cookie(COOKIE_NAME).extract()
                .cookie(COOKIE_NAME);

        // No header
        RestAssured.given().cookie(COOKIE_NAME, token).body("testName").contentType(ContentType.TEXT)
                .when().post("csrfTokenPostBody").then().statusCode(400);

        // Wrong header
        RestAssured.given().cookie(COOKIE_NAME, token).header(HEADER_NAME, "WRONG").body("testName")
                .contentType(ContentType.TEXT)
                .when().post("csrfTokenPostBody").then().statusCode(400);

        // Correct header
        RestAssured.given().cookie(COOKIE_NAME, token).header(HEADER_NAME, token).body("testName")
                .contentType(ContentType.TEXT)
                .when().post("csrfTokenPostBody").then().statusCode(200).body(equalTo("testName"));
    }

    @Path("")
    public static class TestResource {

        @jakarta.inject.Inject
        Template csrfToken;

        @GET
        @Path("/csrfTokenForm")
        @Produces(MediaType.TEXT_HTML)
        public TemplateInstance getCsrfTokenForm() {
            return csrfToken.instance();
        }

        @POST
        @Path("/csrfTokenForm")
        @Consumes(MediaType.APPLICATION_FORM_URLENCODED)
        @Produces(MediaType.TEXT_PLAIN)
        public Uni<String> postCsrfTokenForm(@FormParam("name") String userName) {
            return Uni.createFrom().item(userName);
        }

        @POST
        @Path("/csrfTokenPost")
        @Produces(MediaType.TEXT_PLAIN)
        public Uni<String> postJson() {
            return Uni.createFrom().item("no user");
        }

        @POST
        @Path("/csrfTokenPostBody")
        @Consumes(MediaType.TEXT_PLAIN)
        @Produces(MediaType.TEXT_PLAIN)
        public Uni<String> postJson(String body) {
            return Uni.createFrom().item(body);
        }
    }
}
